const dailyPosts=[{id:'daily-walk',cat:'Fun & Social',title:'今天提前一站下车，捡到了半小时的自由。',desc:'没戴耳机，也没急着回家。原来每天路过的那条街，傍晚这么好看。',author:'小禾',time:'生活日常 · 散步',likes:38,plays:'126',bg:'#e8ded2',daily:true,body:'最近总觉得一天过得太快，今天索性提前一站下车。绕进一条没走过的街，看别人遛狗，等红灯的时候抬头看了会儿天。没有发生什么特别的事，但回到家的时候，心情好像真的松了一点。\n\n如果今天也有点累，就给自己留一小段不赶路的时间吧。'},{id:'daily-dinner',cat:'Fun & Social',title:'冰箱只剩两个番茄，晚饭也没敷衍。',desc:'给自己煮了一碗番茄鸡蛋面。洗碗之前，决定先把这顿小小的幸福记下来。',author:'阿宁的饭桌',time:'生活日常 · 一人食',likes:56,plays:'204',bg:'#f7e8d5',daily:true,body:'本来已经打开外卖软件了，后来想起冰箱里还有两个番茄。鸡蛋炒得有一点点焦边，番茄多煮一会儿，汤汁就会浓起来。端着碗坐到窗边，突然觉得自己做饭也不一定是很费劲的事。\n\n没有精确称重，就是普通的一人份。下面是我的小步骤，想试的话可以边做边勾。'}];
works.unshift(...dailyPosts);
const dailyStageBefore=stage;stage=function(w){if(w.id==='daily-walk')return `<div class="slice daily-walk"><img src="assets/evening-walk.jpg" alt="傍晚阳光下，一位行人牵着狗走过街道" loading="lazy"><span class="daily-photo-tag">下班之后 / 慢一点也没关系</span><div class="daily-poll"><p>下班后，你更想怎么放松？</p><div><button type="button" data-mood="散散步">散散步</button><button type="button" data-mood="回家躺着">回家躺着</button><button type="button" data-mood="吃点好的">吃点好的</button></div><small role="status">选一个，记录此刻的心情</small></div></div>`;if(w.id==='daily-dinner')return `<div class="slice daily-recipe"><div class="recipe-top"><span>阿宁的厨房便签</span><span>一人食 / 家常面</span></div><h3>认真吃饭，<br>也是一件正经事。</h3><div class="recipe-list"><label><input type="checkbox" data-recipe> 番茄炒软，加水煮出汤汁</label><label><input type="checkbox" data-recipe> 放入面条和炒好的鸡蛋</label><label><input type="checkbox" data-recipe> 煮熟调味，撒葱花，开饭</label></div><div class="recipe-status" role="status">0 / 3 · 做过一步，就勾一下</div></div>`;return dailyStageBefore(w)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-mood]');if(!b)return;const poll=b.closest('.daily-poll');poll.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));poll.querySelector('small').textContent='今天选「'+b.dataset.mood+'」· 给自己一点时间';});
document.addEventListener('change',e=>{if(!e.target.matches('[data-recipe]'))return;const recipe=e.target.closest('.daily-recipe'),n=recipe.querySelectorAll('input:checked').length;recipe.querySelector('.recipe-status').textContent=n===3?'3 / 3 · 好好吃饭，今天也辛苦啦。':n+' / 3 · 做过一步，就勾一下'});
const dailyRenderBefore=render;render=function(){dailyRenderBefore();dailyPosts.forEach(w=>{const card=document.querySelector('#card-'+w.id);if(!card)return;card.classList.add('daily-post');card.querySelector('.delivery-badge').textContent='日常分享 · 示例Slice';card.querySelector('.card-author').innerHTML=escapeHtml(w.author)+' <span>· '+w.plays+' 次浏览</span>';card.querySelector('[data-open]').textContent='读全文 ↗';card.querySelector('[data-remix]').textContent='写同款';})};
const dailyOpenBefore=openWork;openWork=function(id,remix=false){const w=dailyPosts.find(w=>w.id===id);if(w&&remix){openCreator({title:'',desc:'',cat:'Fun & Social',template:'draw',author:'好奇心Slicer'});toast('写下你的日常，也可以切换到「描述生成 Slice」');return}dailyOpenBefore(id,remix);if(w){document.querySelector('#dialog-mode').textContent='LIFE NOTES · 生活日常';document.querySelector('#dialog-desc').textContent=w.body;document.querySelector('#dialog-desc').style.whiteSpace='pre-line';document.querySelector('#full-work-panel')?.remove();const note=document.createElement('section');note.id='full-work-panel';note.innerHTML=`<div class="full-heading"><span>把普通的一天，也好好收起来。</span><button data-save="${w.id}">${libraryIds.has(w.id)?'✓ 已收藏':'＋ 收藏到 Library'}</button></div><p class="daily-disclaimer">虚构作者与生活情境，用于展示日常发帖。${id==='daily-walk'?'<br>配图：<a href="https://unsplash.com/pt-br/fotografias/m7pisy5t6Ak" target="_blank" rel="noopener noreferrer">Maxim Tolchinskiy / Unsplash</a>，非作者实拍。':''}</p>`;document.querySelector('#dialog-stage').after(note)}};
render();if(location.hash.startsWith('#work=daily-'))openWork(location.hash.slice(6));
